      <line x1="160" y1="45" x2="249" y2="172" stroke={stroke} strokeWidth="1.6" />
      {/* 中心角のマーク（O のところ・下向き） */}
      <path d="M 145 156 A 20 20 0 0 0 175 156" fill="none" stroke={accent} strokeWidth="1.3" />
      {/* 円周角のマーク（P のところ） */}
