  const curve = pts.map(([x, y], i) => `${i === 0 ? "M" : "L"} ${x} ${y}`).join(" ");
  // ぬった部分（下のはし 130 から 上のはし 290 まで）
  const area = "M 130 205 L 130 161 L 170 147 L 210 131 L 250 113 L 290 93 L 290 205 Z";
